 "content": "from collections import deque


def transform(grid):
    """Extend the outward diagonal arms of same-color diagonal motifs."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    colored = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] != background]
    if not colored:
        return out
    center_r = sum(r for r, _ in colored) / len(colored)
    center_c = sum(c for _, c in colored) / len(colored)

    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            component = []
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                rr, cc = q.popleft()
                component.append((rr, cc))
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = rr + dr, cc + dc
                        if (0 <= nr < h and 0 <= nc < w and
                                grid[nr][nc] == color and (nr, nc) not in seen):
                            seen.add((nr, nc))
                            q.append((nr, nc))
            if len(component) < 2:
                continue

            members = set(component)
            endpoints = []
            for rr, cc in component:
                neighbors = [(rr + dr, cc + dc) for dr in (-1, 0, 1)
                             for dc in (-1, 0, 1) if (dr, dc) != (0, 0)
                             and (rr + dr, cc + dc) in members]
                if len(neighbors) != 1:
                    continue
                pr, pc = neighbors[0]
                dr, dc = rr - pr, cc - pc
                if abs(dr) == 1 and abs(dc) == 1:
                    distance = (rr - center_r) ** 2 + (cc - center_c) ** 2
                    endpoints.append((distance, rr, cc, dr, dc))

            if not endpoints:
                continue
            farthest = max(item[0] for item in endpoints)
            # Symmetric outward arms (as in a fork) are both extended.
            for distance, rr, cc, dr, dc in endpoints:
                if farthest - distance > 1e-9:
                    continue
                nr, nc = rr + dr, cc + dc
                while 0 <= nr < h and 0 <= nc < w:
                    if out[nr][nc] not in (background, color):
                        break
                    out[nr][nc] = color
                    nr += dr
                    nc += dc
    return out


